    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, []).value;
  const totals1 = invoiceTotals(issued1);
  invoices.push(issued1);

  // Partially paid invoice (overdue)
  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-10',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
    terms: 'NET14',
  });
  inv2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;
  const totals2 = invoiceTotals(inv2);
  const payment2 = Math.floor(totals2.total / 2);
  inv2 = recordPayment(inv2, { amount: payment2, date: '2026-09-11' }).value;
  invoices.push(inv2);

  // Paid invoice (not overdue)
  let inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  inv3 = issueInvoice(inv3.value, ['INV-2026-0002']).value;
  const totals3 = invoiceTotals(inv3);
  inv3 = recordPayment(inv3, { amount: totals3.total, date: '2026-10-02' }).value;
  invoices.push(inv3);

  const result = dashboard(invoices, '2026-10-31');

  // Verify counts
  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.partially_paid, 1);
  assert.equal(result.counts.paid, 1);

  // Verify outstanding (issued + partially_paid)
  const expected_outstanding = totals1.total + (totals2.total - payment2);
  assert.equal(result.outstanding, expected_outstanding);

  // Verify overdue
  assert.equal(result.overdue.count, 2);
  assert(result.overdue.amount > 0);

  // Verify top customers
  assert(result.topCustomers.length >= 2);
});

