    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0002']).value;

  const result = dashboard([issued1, issued2, issued3], '2026-10-31');
  assert(result.topCustomers[0].due > result.topCustomers[1].due);
  assert(result.topCustomers[1].due > result.topCustomers[2].due);
});

test('dashboard excludes fully paid invoices from top customers', () => {
  let inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;
  const totals1 = invoiceTotals(inv1);
  inv1 = recordPayment(inv1, { amount: totals1.total, date: '2026-10-02' }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;

  const result = dashboard([inv1, issued2], '2026-10-31');
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
});

test('dashboard with multiple invoices from same customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(inv1.value, []).value;
  const totals1 = invoiceTotals(issued1);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;
  const totals2 = invoiceTotals(issued2);

  const result = dashboard([issued1, issued2], '2026-10-31');
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert.equal(result.topCustomers[0].due, totals1.total + totals2.total);
});
